INSERT INTO `window_target` (`group_id`, `total`, `average`, `minimum`, `maximum`, `last`, `day`) SELECT `group_id`, `total`, `average`, `minimum`, `maximum`, `last`, `day` FROM (WITH dh_window_clocked AS (SELECT dh_window_input.*, PROCTIME() AS `__dh_window_clock` FROM (SELECT `key`, `seq`, `value`, `group_id`, `text` FROM `window_source`) dh_window_input), dh_windowed AS (SELECT * FROM TABLE(TUMBLE(TABLE dh_window_clocked, DESCRIPTOR(`__dh_window_clock`), INTERVAL '2.000' SECOND))) SELECT `group_id`, `total` AS `total`, `average` AS `average`, `minimum` AS `minimum`, `maximum` AS `maximum`, CASE WHEN COALESCE(`__dh_window_last_0`[1], '') = 'a' THEN CAST(CAST(`__dh_window_last_0`[5] AS STRING) AS STRING) WHEN COALESCE(`__dh_window_last_0`[1], '') = 'b' THEN CAST(CAST(`__dh_window_last_0`[5] AS STRING) AS STRING) ELSE NULL END AS `last`, `day` AS `day` FROM (SELECT `group_id`, DH_WINDOW_PICK(ARRAY[CAST(`key` AS STRING), CAST(`seq` AS STRING), CAST(`value` AS STRING), CAST(`group_id` AS STRING), CAST(`text` AS STRING)], '1|F|1000|1048576|1:A:N|1') AS `__dh_window_budget`, CAST(SUM(CASE WHEN COALESCE(CAST(`key` AS STRING), '') = 'a' THEN CAST(`value` AS DECIMAL(38,18)) ELSE NULL END) AS DECIMAL(38,18)) AS `total`, CAST(AVG(CASE WHEN COALESCE(CAST(`key` AS STRING), '') = 'a' THEN CAST(`value` AS DOUBLE) ELSE NULL END) AS DOUBLE) AS `average`, CAST(MIN(CASE WHEN COALESCE(CAST(`key` AS STRING), '') = 'a' THEN CAST(`value` AS DOUBLE) ELSE NULL END) AS DOUBLE) AS `minimum`, CAST(MAX(CASE WHEN COALESCE(CAST(`key` AS STRING), '') = 'a' THEN CAST(`value` AS DOUBLE) ELSE NULL END) AS DOUBLE) AS `maximum`, DH_WINDOW_PICK(ARRAY[CAST(`key` AS STRING), CAST(`seq` AS STRING), CAST(`value` AS STRING), CAST(`group_id` AS STRING), CAST(`text` AS STRING)], '1|L|1000|1048576|1:A:N|1') FILTER (WHERE COALESCE(CAST(`key` AS STRING), '') = 'a' OR COALESCE(CAST(`key` AS STRING), '') = 'b') AS `__dh_window_last_0`, CAST(MAX(CASE WHEN COALESCE(CAST(`key` AS STRING), '') = 'day' THEN TO_TIMESTAMP(CAST(CASE WHEN CAST(`text` AS STRING) = 'missing' THEN NULL ELSE `text` END AS STRING), 'yyyy-MM-dd') ELSE NULL END) AS TIMESTAMP) AS `day` FROM dh_windowed GROUP BY window_start, window_end, `group_id`) dh_window_results WHERE `__dh_window_budget` IS NOT NULL) dh_output;